# Generated by build.py from recipe.yml for recipe dict-match-words-by-prefix. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'words' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'words/apple'), "a round fruit`n")
[IO.File]::WriteAllText((Join-Path $PWD 'words/apricot'), "a small orange fruit`n")
[IO.File]::WriteAllText((Join-Path $PWD 'words/banana'), "a long yellow fruit`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'words', 'dict://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s dict://127.0.0.1:8080/m:ap:*:prefix } finally { Stop-Process $server0 }
